using System;using System.IO;using System.Text.Json;using WakeRemote;using Xunit;namespace WakeRemote.Tests;
public class ProtocolTests{[Fact]public void MatchesFixture(){var path=Path.Combine(AppContext.BaseDirectory,"test-vectors.json");if(!File.Exists(path))path=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../../shared/test-vectors.json"));using var json=JsonDocument.Parse(File.ReadAllText(path));var v=json.RootElement.GetProperty("vectors")[0];var key=Convert.FromHexString(v.GetProperty("key_hex").GetString()!);var nonce=Convert.FromHexString(v.GetProperty("nonce").GetString()!);var signed=Protocol.Sign(key,"main-pc",v.GetProperty("timestamp").GetInt64(),nonce);Assert.Equal(v.GetProperty("canonical").GetString(),signed.Canonical);Assert.Equal(v.GetProperty("signature").GetString(),signed.Signature);}}
